import { blockedNotice, harnessHooks, shQuote } from './settings.js';
/**
 * The plugin's hooks: the same handlers as a project install, except that PreToolUse runs hooks/pre-tool.sh
 * inside the plugin. The Claude plugin directory refuses a hook command the shell computes (the inline program
 * of guardedPreTool reads stdin with a command substitution) and follows plain shell scripts, so the script keeps
 * the same rules - quiet without the CLI, one retry, then exit 2 with the reason - without `$(` or backticks.
 * For a hook that never approves a call (B273) the directory also wants no printf conversions or backslash escapes
 * and no `2>&1`: the notice is echoed to standard error, the attempts are an if/elif, and redirects stay separate.
 */
export function renderPluginHooks(cli) {
    const hooks = harnessHooks(cli);
    hooks.PreToolUse[0].hooks[0].command = '"${CLAUDE_PLUGIN_ROOT}/hooks/pre-tool.sh"';
    for (const group of Object.values(hooks).flat()) {
        for (const handler of group.hooks) {
            if (handler.command !== undefined)
                handler.command = separateRedirects(handler.command);
        }
    }
    return [
        { path: 'hooks/hooks.json', content: `${JSON.stringify({ hooks }, null, 2)}\n` },
        { path: 'hooks/pre-tool.sh', content: preToolScript(cli), executable: true },
    ];
}
/** `2>&1` after a redirect of standard output to /dev/null, spelled as its own redirect of standard error. */
function separateRedirects(command) {
    return command.split('>/dev/null 2>&1').join('>/dev/null 2>/dev/null');
}
function preToolScript(cli) {
    const bin = cli.split(/\s+/)[0];
    const attempt = `${cli} hook pre-tool < "$in" > "$in.out"`;
    const notice = blockedNotice(cli).replace(/`/g, '"');
    return [
        '#!/bin/sh',
        '# Generated by sdlc plugin build; do not edit.',
        `command -v ${bin} >/dev/null 2>/dev/null || exit 0`,
        'in="${TMPDIR:-/tmp}/sdlc-pre-tool-$$"',
        'trap \'rm -f "$in" "$in.out"\' EXIT',
        'cat > "$in"',
        `if ${attempt}; then`,
        '  :',
        `elif ${attempt}; then`,
        '  :',
        'else',
        `  echo ${shQuote(notice)} >&2`,
        '  exit 2',
        'fi',
        'cat "$in.out"',
        '',
    ].join('\n');
}
